import type {CopilotGenerateCommitMessageAuthInfo} from '@github-ui/code-view-types'
import {CopilotAuthTokenProvider} from '@github-ui/copilot-auth-token'
import {makeCAPIRequest} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import {CopilotChatMessageStreamer} from '@github-ui/copilot-chat/utils/copilot-chat-message-streamer'
import {useQuery} from '@github-ui/react-query'
import {sendStats} from '@github-ui/stats'
import {useClickAnalytics} from '@github-ui/use-analytics'

import {
  type AgentResponse,
  calculateInputTokenUsage,
  calculateOutputTokenUsage,
  createDiffReferences,
  dryMessagesPrompt,
  handleStreamingMessage,
  validateAndExtractCommitMessage,
  type ValidatedCommitMessage,
} from '../utilities/generate-commit-message-helpers'

export type useGenerateCommitMessageInfo = {
  copilotGenerateCommitMessageAuthInfo: CopilotGenerateCommitMessageAuthInfo | undefined
  initialPath: string
  completeFilePath: string
  initialFileContent: string
  currentFileContent: string
  placeholderMessage: string
  isNewFile?: boolean
}

function returnFallback(message: string): ValidatedCommitMessage {
  return {
    commitMessage: message,
    description: '',
  }
}

// CAPI status codes that are expected and shouldn't trigger error stats
const EXPECTED_ERROR_STATUS_CODES = [
  402, // "Payment Required" - Response when free user has hit their quota and we should restrict access
  429, // "Too Many Requests" - CAPI rate limiting response
]

function sendErrorAndLatencyStats(incrementKey: PlatformBrowserIncrementKey, startTime: number) {
  const duration = performance.now() - startTime

  sendStats({
    incrementKey,
    requestUrl: window.location.href,
  })

  sendStats({
    distributionKey: 'GENERATED_COMMIT_MESSAGE_LATENCY',
    distributionValue: Math.round(duration),
    requestUrl: window.location.href,
  })
}

export function useGenerateCommitMessage(
  placeholderMessage: string,
  copilotGenerateCommitMessageAuthInfo?: CopilotGenerateCommitMessageAuthInfo | undefined,
  initialPath?: string,
  completeFilePath?: string,
  initialFileContent?: string,
  currentFileContent?: string,
  isNewFile?: boolean,
  generatedMessages?: string[],
  regenerateCallCount?: number,
) {
  // Check if we should use fallback immediately
  const shouldUseFallback =
    copilotGenerateCommitMessageAuthInfo === undefined ||
    !copilotGenerateCommitMessageAuthInfo.copilotAccessAllowed ||
    initialFileContent === undefined ||
    currentFileContent === undefined ||
    initialPath === undefined ||
    completeFilePath === undefined ||
    (!initialFileContent && !currentFileContent) // Adding an empty new file we should use placeholderMessage

  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const {data: generatedCommitMessage, isFetching} = useQuery({
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
    queryKey: ['generate-commit-message', currentFileContent, completeFilePath, regenerateCallCount],
    queryFn: async () => {
      const startTime = performance.now()

      const authTokenProvider = new CopilotAuthTokenProvider(
        copilotGenerateCommitMessageAuthInfo!.ssoOrganizations.map(org => org.id),
      )
      const token = await authTokenProvider.getAuthToken()

      const references =
        // If this is a new file and the content is present but the same that means the content was added before the file name
        // This edgecase will result in the diff being just a file name unless we handle it manually
        isNewFile && initialFileContent === currentFileContent
          ? createDiffReferences('', currentFileContent!, initialPath!, completeFilePath!)
          : createDiffReferences(initialFileContent!, currentFileContent!, initialPath!, completeFilePath!)

      let content = ''

      // Add previously generated messages to provide context for generating a new, different message
      if (generatedMessages && generatedMessages.length > 0) {
        content += dryMessagesPrompt(generatedMessages)
      }

      const result = await makeCAPIRequest({
        authToken: token,
        basePath: copilotGenerateCommitMessageAuthInfo!.apiUrl,
        body: {
          messages: [
            {
              role: 'user',
              content,
              // eslint-disable-next-line camelcase
              copilot_references: references,
            },
          ],
          temperature: 0.3,
          // eslint-disable-next-line camelcase
          response_format: {
            type: 'json_schema',
            // eslint-disable-next-line camelcase
            json_schema: {
              description: 'The schema to abide by when generating commit message output',
              name: 'commit_message_response',
              strict: true,
              schema: {
                type: 'object',
                properties: {
                  title: {
                    type: 'string',
                    description: 'The commit message title/summary',
                  },
                  description: {
                    type: 'string',
                    description: 'The commit message description/body',
                  },
                },
                required: ['title', 'description'],
                additionalProperties: false,
              },
            },
          },
        },
        integrationId: 'commit-msg-gen',
        method: 'POST',
        path: '/agents/github-commit-message-generation',
        streamingResponse: true,
      })

      try {
        if (!result.ok) {
          throw new Error('Failed to generate commit message')
        }

        const reader = result.body?.getReader()
        if (!reader) {
          throw new Error('No reader found in response body')
        }

        const streamer = new CopilotChatMessageStreamer<AgentResponse>(reader)
        const message = await handleStreamingMessage(streamer)

        const validatedMessage = validateAndExtractCommitMessage(message)

        // Track successful generation
        sendErrorAndLatencyStats('GENERATED_COMMIT_MESSAGE_SUCCESS', startTime)

        // Track input/output token usage and send to hydro
        const inputTokenCount = calculateInputTokenUsage(references)
        const outputTokenCount = calculateOutputTokenUsage(message)
        const eventData = {
          category: 'copilot_generate_commit_message',
          action: 'generate',
          // eslint-disable-next-line camelcase
          input_token_count: inputTokenCount,
          // eslint-disable-next-line camelcase
          output_token_count: outputTokenCount,
          // eslint-disable-next-line camelcase
          total_token_count: inputTokenCount + outputTokenCount,
        }
        sendClickAnalyticsEvent(eventData)

        if (validatedMessage) {
          return validatedMessage
        } else {
          return returnFallback(placeholderMessage)
        }
      } catch {
        // Track general errors (network, auth, etc.)
        // Don't send error stats for expected quota/auth errors
        if (!EXPECTED_ERROR_STATUS_CODES.includes(result.status)) {
          sendErrorAndLatencyStats('GENERATED_COMMIT_MESSAGE_ERROR', startTime)
        }

        return returnFallback(placeholderMessage)
      }
    },
    enabled: !shouldUseFallback,
    meta: {action: 'get-generated-commit-message'},
  })

  // Return fallback immediately if conditions are not met
  if (shouldUseFallback) {
    return {
      generatedCommitMessage: returnFallback(placeholderMessage),
      isFetching: false,
    }
  }

  return {generatedCommitMessage, isFetching}
}
