import type {CopilotChatMessageStreamer} from '@github-ui/copilot-chat/utils/copilot-chat-message-streamer'
import type {DiffHunkReference} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {getCopilotExperiments, setCopilotExperiments} from '@github-ui/copilot-chat/utils/experiments'
import {useClickAnalytics} from '@github-ui/use-analytics'
import type {ParsedDiff} from 'diff'
import {formatPatch, structuredPatch} from 'diff'
import {useCallback} from 'react'

export interface ChangedFile {
  patch: ParsedDiff
  path: string
}

export type AgentResponse = {
  choices: Array<{message: Message}>
  type: undefined
}

type Message = {
  role: string
  content: string
}

type DiffHunkAgentReference = {
  type: 'github.diff-hunk'
  data: DiffHunkReference
}

export type ValidatedCommitMessage = {
  commitMessage: string
  description?: string
}

export type FileStatus = 'A' | 'D' | 'M' | 'R'

// Rough estimate of token count (4 characters per token)
const CHARACTERS_PER_TOKEN = 4

export async function handleStreamingMessage(
  streamer: CopilotChatMessageStreamer<AgentResponse>,
): Promise<AgentResponse> {
  const messages: AgentResponse[] = []

  for await (const message of streamer.stream()) {
    messages.push(message)
  }

  if (messages.length === 0) {
    throw new Error('No messages found in stream')
  }

  if (messages.length > 1) {
    throw new Error('More than one message found in stream')
  }

  const message = messages[0]!
  return message
}

export function validateAndExtractCommitMessage(agentResponse: AgentResponse): ValidatedCommitMessage | undefined {
  const commitMessageResponse = agentResponse?.choices?.[0]?.message

  if (!commitMessageResponse) {
    throw new Error('No message found in agent response')
  }

  if (!commitMessageResponse.content) {
    throw new Error('No content found in commit message')
  }

  let parsedContent: {title: string; description: string}

  try {
    parsedContent = JSON.parse(commitMessageResponse.content)
  } catch {
    throw new Error('Invalid JSON in commit message response')
  }

  if (parsedContent.title === undefined || parsedContent.title === null) {
    throw new Error('No title field found in commit message response')
  }

  if (parsedContent.description === undefined || parsedContent.description === null) {
    throw new Error('No description field found in commit message response')
  }

  if (parsedContent.title.trim() === '') return

  return {
    commitMessage: parsedContent.title,
    description: parsedContent.description,
  }
}

function formatChangedFilesAsDiffs(files: ChangedFile[]): DiffHunkAgentReference[] {
  return files.map(file => {
    return {
      type: 'github.diff-hunk',
      data: {
        type: 'diff-hunk',
        changeReference: '',
        fileName: file.path,
        headerContext: '',
        diff: formatPatch(file.patch),
      },
    }
  })
}

function formatChangedFiles(
  initialFileContent: string,
  currentFileContent: string,
  initialPath: string,
  completeFilePath: string,
): ChangedFile[] {
  const patch = structuredPatch(initialPath, completeFilePath, initialFileContent, currentFileContent)

  return [
    {
      patch,
      path: completeFilePath,
    },
  ]
}

export function createDiffReferences(
  initialFileContent: string,
  currentFileContent: string,
  initialPath: string,
  completeFilePath: string,
): DiffHunkAgentReference[] {
  const files = formatChangedFiles(initialFileContent, currentFileContent, initialPath, completeFilePath)

  const references = formatChangedFilesAsDiffs(files)

  return references
}

export function getFileStatus(
  isNewFile: boolean,
  isDeletedFile: boolean,
  contentChanged?: boolean,
  oldPath?: string,
  fileName?: string,
): FileStatus {
  if (isDeletedFile) {
    return 'D'
  }

  return isNewFile ? 'A' : fileName !== oldPath ? (contentChanged ? 'M' : 'R') : 'M'
}

export function useTrackWebCommitAcceptance() {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  return useCallback(
    async ({
      message,
      description,
      placeholderMessage,
      generatedCommitMessage,
      showingGeneratedCommitMessage,
      showingGeneratedCommitDescription,
      isNewFile,
      isDelete,
      contentChanged,
      oldPath,
      fileName,
      content,
      regenerateCallCount,
      version,
    }: {
      message: string
      description: string
      placeholderMessage: string
      generatedCommitMessage?: ValidatedCommitMessage | null
      showingGeneratedCommitMessage: boolean
      showingGeneratedCommitDescription: boolean
      isNewFile: boolean
      isDelete: boolean
      contentChanged?: boolean
      oldPath?: string
      fileName?: string
      content?: string
      regenerateCallCount?: number
      version?: string
    }): Promise<void> => {
      const eventData = {
        category: 'web_commit_dialog',
        action: 'submit',
        // eslint-disable-next-line camelcase
        showing_generated_commit_message: showingGeneratedCommitMessage,
        // eslint-disable-next-line camelcase
        showing_generated_commit_description: showingGeneratedCommitDescription,
        // eslint-disable-next-line camelcase
        full_message_acceptence: message === placeholderMessage || message === generatedCommitMessage?.commitMessage,
        // eslint-disable-next-line camelcase
        message_similarity: stringSimilarity(message, generatedCommitMessage?.commitMessage ?? ''),
        // eslint-disable-next-line camelcase
        full_description_acceptence: description === generatedCommitMessage?.description,
        // eslint-disable-next-line camelcase
        description_similarity: stringSimilarity(description, generatedCommitMessage?.description ?? ''),
        // eslint-disable-next-line camelcase
        message_description_similarity: stringSimilarity(
          generatedCommitMessage?.commitMessage ?? '',
          generatedCommitMessage?.description ?? '',
        ),
        // eslint-disable-next-line camelcase
        file_status: getFileStatus(isNewFile, isDelete, contentChanged, oldPath, fileName),
        // eslint-disable-next-line camelcase
        empty_description: description.trim() === '',
        // eslint-disable-next-line camelcase
        change_chars_count: content?.replace(/\s+/g, '').length,
        // eslint-disable-next-line camelcase
        regenerate_call_count: regenerateCallCount ?? 0,
        version,
      }

      sendClickAnalyticsEvent(eventData)
    },
    [sendClickAnalyticsEvent],
  )
}

export function useTrackWebCommitRegenerated() {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  return useCallback(
    async ({
      version,
      regenerateCallCount,
      uniquelyGeneratedMessagesCount,
    }: {
      version?: string
      regenerateCallCount: number
      uniquelyGeneratedMessagesCount: number
    }): Promise<void> => {
      const eventData = {
        category: 'web_commit_dialog',
        action: 'regenerate',
        version,
        // eslint-disable-next-line camelcase
        regenerate_call_count: regenerateCallCount,
        // eslint-disable-next-line camelcase
        uniquely_generated_messages_count: uniquelyGeneratedMessagesCount,
      }
      sendClickAnalyticsEvent(eventData)
    },
    [sendClickAnalyticsEvent],
  )
}

export function calculateInputTokenUsage(copilotReferences: DiffHunkAgentReference[]): number {
  if (!copilotReferences || copilotReferences.length === 0 || !copilotReferences[0]?.data) {
    throw new Error('Copilot references are empty or undefined')
  }

  let requestCharCount = 0
  const referenceData = copilotReferences[0]?.data
  const {changeReference, diff, fileName, headerContext} = referenceData
  requestCharCount += changeReference.length + diff.length + fileName.length + headerContext.length

  return Math.ceil(requestCharCount / CHARACTERS_PER_TOKEN)
}

export function calculateOutputTokenUsage(commitMessage: AgentResponse) {
  if (!commitMessage || !commitMessage.choices[0]?.message.content) {
    throw new Error('Commit message is empty or undefined')
  }
  const chars = commitMessage.choices[0].message.content.length

  return Math.ceil(chars / CHARACTERS_PER_TOKEN)
}

// Manage adding experiment headers for CAPI to toggle behavior in the commit message agent
// experiments example:
// [{
//   flagEnabled: commitAgentVersioningEnabled,
//   experimentName: 'Commit-Agent-Version=1',
// }]
export function setCAPIExperimentForCommitMessageAgent(
  experiments: Array<{flagEnabled: boolean; experimentName: string}>,
) {
  const existingExperiments = getCopilotExperiments()
  let updatedExperiments = [...existingExperiments]
  let shouldUpdateExperiments = false

  for (const {flagEnabled, experimentName} of experiments) {
    if (flagEnabled) {
      if (!updatedExperiments.includes(experimentName)) {
        updatedExperiments.push(experimentName)
        shouldUpdateExperiments = true
      }
    } else {
      // Need to clear experiments so when we toggle flags off it will remove the header
      if (updatedExperiments.includes(experimentName)) {
        updatedExperiments = updatedExperiments.filter(exp => exp !== experimentName)
        shouldUpdateExperiments = true
      }
    }
  }

  if (shouldUpdateExperiments) {
    setCopilotExperiments(updatedExperiments)
  }
}

// Based on https://www.npmjs.com/package/string-similarity-js
function stringSimilarity(
  str1: string,
  str2: string,
  substringLength: number = 2,
  caseSensitive: boolean = false,
): number {
  if (!caseSensitive) {
    str1 = str1.toLowerCase()
    str2 = str2.toLowerCase()
  }

  if (str1.length < substringLength || str2.length < substringLength) return 0

  const map = new Map()
  for (let i = 0; i < str1.length - (substringLength - 1); i++) {
    const substr1 = str1.slice(i, i + substringLength)
    map.set(substr1, map.has(substr1) ? map.get(substr1) + 1 : 1)
  }

  let match = 0
  for (let j = 0; j < str2.length - (substringLength - 1); j++) {
    const substr2 = str2.slice(j, j + substringLength)
    const count = map.has(substr2) ? map.get(substr2) : 0
    if (count > 0) {
      map.set(substr2, count - 1)
      match++
    }
  }

  return (match * 2) / (str1.length + str2.length - (substringLength - 1) * 2)
}

export function dryMessagesPrompt(generatedMessages: string[]): string {
  let content =
    '## Additional context from previous messages\n\nDo not repeat or closely paraphrase any of these previously used messages. Instead, generate a new commit message that has a different focus, wording, or level of detail. If you cannot think of a new message, change the perspective, focus on different details, or rephrase creatively.\n\n<!-- BEGIN PREVIOUS MESSAGES -->\n'
  for (const message of generatedMessages) {
    content += `### Previous message\n\n${message}\n\n`
  }
  content += '<!-- END PREVIOUS MESSAGES -->\n\n'
  return content
}
